CustomField.formula:
IF(
 AND(
  OR (
      SBQQ__Bundle__c, !SBQQ__Bundled__c
      ),
      SBQQ__RegularPrice__c > 0,
      SBQQ__Quote__r.SBQQ__PriceBook__r.Name == 'Global Pricebook'
     ),
/*Calc Additional Discount based on Price*/
((  (SBQQ__ProratedListPrice__c - ( SBQQ__ProratedListPrice__c * Volume_Discount__c )) - ( SBQQ__CustomerPrice__c + SBQQ__TermDiscount__c ) ) /
    (SBQQ__ProratedListPrice__c - ( SBQQ__ProratedListPrice__c * Volume_Discount__c ))*1) * (1-SBQQ__DiscountTier__r.SBQQ__Discount__c) +
    SBQQ__DiscountTier__r.SBQQ__Discount__c, 0
   )


/* ONLY WORKS IF ADDITIONAL DISCOUNT IS IN % AND NOT USD
( SBQQ__Discount__c  * (1-SBQQ__DiscountTier__r.SBQQ__Discount__c)) + SBQQ__DiscountTier__r.SBQQ__Discount__c

*/
